  /**
   * @method
   * @name paradex#watchTickers
   * @description watches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for all markets of a specific
   * list
   * @see
   * https://docs.paradex.trade/ws/web-socket-channels/markets-summary/markets-summary
   * @param {string[]} symbols unified symbol of the market to fetch the ticker
   * for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  watchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any channel = std::string("markets_summary");
                 ccxt::any url =
                     ::getValue(::getValue(this->urls, std::string("api")),
                                std::string("ws"));
                 ccxt::any request = ccxt::dict{
                     {std::string("jsonrpc"), std::string("2.0")},
                     {std::string("method"), std::string("subscribe")},
                     {std::string("params"),
                      ccxt::dict{
                          {std::string("channel"), channel},
                      }},
                 };
                 ccxt::any messageHashes = ccxt::list{};
                 if (isTrue(isTrue(!isEqual(symbols, ccxt::any{})) &&
                            isTrue(isArray(symbols)))) {
                   for (ccxt::any i = 0; isLessThan(i, getArrayLength(symbols));
                        postFixIncrement(i)) {
                     ccxt::any messageHash = add(add(channel, std::string(".")),
                                                ::getValue(symbols, i));
                     arrayPush(messageHashes, messageHash);
                   }
                 } else {
                   arrayPush(messageHashes, channel);
                 }
                 ccxt::any newTicker = awaitValue(this->watchMultiple(
                     url, messageHashes, this->deepExtend(request, params),
                     messageHashes));
                 if (isTrue(this->newUpdates)) {
                   ccxt::any result = ccxt::dict{};
                   ::setValue(result,
                              ::getValue(newTicker, std::string("symbol")),
                              newTicker);
                   return result;
                 }
                 return this->filterByArray(this->tickers,
                                            std::string("symbol"), symbols);
               })
        .share();
  }

